//! docs/host-contract.md's generated part is `typedpress::host_contract::render_doc()`. When this fails,
//! run `TP_UPDATE_DOCS=1 cargo test --test host_contract` and commit the doc.

const START: &str =
    "<!-- generated by `cargo test --test host_contract` from src/host_contract.rs; do not edit below -->\n";
const END: &str = "<!-- end generated -->";

#[test]
fn the_host_contract_doc_is_generated_from_the_code() {
    let path = concat!(env!("CARGO_MANIFEST_DIR"), "/docs/host-contract.md");
    let doc = std::fs::read_to_string(path).unwrap();
    let (head, rest) = doc.split_once(START).expect("start marker");
    let (_, tail) = rest.split_once(END).expect("end marker");
    let expected = format!("{head}{START}{}{END}{tail}", typedpress::host_contract::render_doc());
    if std::env::var_os("TP_UPDATE_DOCS").is_some() {
        std::fs::write(path, &expected).unwrap();
    }
    assert!(
        doc == expected,
        "docs/host-contract.md is stale: run TP_UPDATE_DOCS=1 cargo test --test host_contract"
    );
}
